const people = [
  { name: "Ada", team: "red", age: 36 },
  { name: "Bob", team: "blue", age: 41 },
  { name: "Cy", team: "red", age: 29 },
];

test("unique by key", () => {
  checkEq(uniqueBy(people, p => p.team).map(p => p.name), ["Ada", "Bob"]);
  checkEq(uniqueBy([3, 1, 3, 2, 1], n => n), [3, 1, 2]);
  checkEq(uniqueBy(["a", "B", "b"], s => s.toLowerCase()), ["a", "B"]);
});

test("pluck and indexBy", () => {
  checkEq(pluck(people, "age"), [36, 41, 29]);
  checkEq(pluck([], "x" as never), []);
  const byTeam = indexBy(people, "team");
  checkEq(byTeam.get("red")?.name, "Cy");
  checkEq(byTeam.size, 2);
});

test("cache drops the least recently used", () => {
  const c = new Cache<string, number>(2);
  c.set("a", 1);
  c.set("b", 2);
  checkEq(c.get("a"), 1);
  c.set("c", 3);
  checkEq([c.get("a"), c.get("b"), c.get("c")], [1, undefined, 3]);
  c.set("a", 10);
  c.set("d", 4);
  checkEq([c.get("a"), c.get("c"), c.get("d")], [10, undefined, 4]);
  checkEq(c.size, 2);
});

